package ranjith;

public class ifelse {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=15,b=12,c=18;
		if(a>b)
			if(a>c)
				System.out.println("biggest "+a);
		else if(b>c)
			System.out.println("biggest "+b);
		else
			System.out.println("biggest "+c);
		//default
		//	System.out.println("enter correct thing");
		

	}

}
